-- ── Resolve parent_id from parent_key ─────────────────────────────────────────
UPDATE game_locations
SET parent_id = (
    SELECT p.id FROM game_locations p WHERE p.key = game_locations.parent_key
)
WHERE parent_key IS NOT NULL
  AND parent_id IS NULL;
